//! `src/reflection/v1.rs` and `v1alpha.rs` are generated by akio-protobuf-build from
//! `proto/grpc/reflection/*/reflection.proto`; the checked-in copies must match. After a
//! generator change: `AKIO_PROTOBUF_BLESS=1 cargo test -p akio-grpc --test reflection_generated`.

use std::path::Path;

#[test]
fn reflection_messages_are_up_to_date() {
    let dir = Path::new(env!("CARGO_MANIFEST_DIR"));
    for v in ["v1", "v1alpha"] {
        let out = akio_protobuf_build::Config::new()
            .include(dir.join("proto"))
            .grpc(false)
            .unknown_fields(false)
            .generate(&[dir.join(format!("proto/grpc/reflection/{v}/reflection.proto"))])
            .unwrap();
        assert_eq!(out.len(), 1);
        assert_eq!(out[0].0, format!("grpc.reflection.{v}.rs"));
        let target = dir.join(format!("src/reflection/{v}.rs"));
        let code = &out[0].1;
        if std::env::var_os("AKIO_PROTOBUF_BLESS").is_some() {
            std::fs::write(&target, code).unwrap();
            continue;
        }
        let have = std::fs::read_to_string(&target).unwrap_or_default();
        assert!(
            have == *code,
            "{} is stale: run AKIO_PROTOBUF_BLESS=1 cargo test -p akio-grpc --test reflection_generated",
            target.display()
        );
    }
}
